// Writes the Klawly guide's docs (issue 524): sections 1 to 4 of FEATURES.md, as a
// string the built-in klawly-guide subagent carries in its prompt. Run it after
// FEATURES.md changes; a node test fails while the generated file is out of date.
// Usage: node build/klawly/guide-bundle.ts [--check]

import { readFileSync, writeFileSync } from 'fs';
import { join } from 'path';

const root = join(import.meta.dirname, '..', '..');
const OUT = 'src/vs/platform/claude/common/klawlyGuideText.ts';

/** Sections 1 to 4 of FEATURES.md: what Klawly has and its own choices, not the upkeep notes or the upstream comparison. */
export function klawlyGuideDocs(features: string): string {
	const text = features.replace(/\r\n/g, '\n');
	const start = text.indexOf('\n## 1.');
	const end = text.indexOf('\n## 5.');
	return text.slice(start < 0 ? 0 : start + 1, end < 0 ? text.length : end).trim();
}

export function klawlyGuideModule(features: string): string {
	return [
		'/*---------------------------------------------------------------------------------------------',
		' *  Copyright (c) Klawly contributors. All rights reserved.',
		' *  Licensed under the MIT License. See License.txt in the project root for license information.',
		' *--------------------------------------------------------------------------------------------*/',
		'',
		'// Generated by build/klawly/guide-bundle.ts from FEATURES.md. Do not edit; run `npm run guide-bundle`.',
		'',
		'/** What Klawly has and its own choices (FEATURES.md sections 1 to 4), for the klawly-guide subagent (issue 524). */',
		`export const KLAWLY_GUIDE_DOCS = ${singleQuoted(klawlyGuideDocs(features))};`,
		'',
	].join('\n');
}

/**
 * A single-quoted string literal (double quotes are for localized strings), with
 * non-ASCII escaped so the source file stays plain ASCII for the hygiene check.
 */
function singleQuoted(text: string): string {
	const body = JSON.stringify(text).slice(1, -1).replace(/\\"/g, '"').replace(/'/g, '\\\'');
	return `'${body.replace(/[\u007f-\uffff]/g, char => `\\u${char.charCodeAt(0).toString(16).padStart(4, '0')}`)}'`;
}

if (process.argv[1] && import.meta.filename === process.argv[1]) {
	const module = klawlyGuideModule(readFileSync(join(root, 'FEATURES.md'), 'utf8'));
	if (process.argv.includes('--check')) {
		// Part of `npm run precommit`, so a FEATURES.md edit can't land with stale guide docs.
		if (readFileSync(join(root, OUT), 'utf8').replace(/\r\n/g, '\n') !== module) {
			console.error(`guide-bundle: ${OUT} is out of date with FEATURES.md; run npm run guide-bundle`);
			process.exit(1);
		}
	} else {
		writeFileSync(join(root, OUT), module);
		console.log(`guide-bundle: wrote ${OUT}`);
	}
}
